export default defineConfig({
  testDir: './e2e/visual',
  globalSetup: './e2e/global-setup.ts',
  outputDir: 'test-results-visual/run',
  snapshotPathTemplate: `${process.env.VISUAL_BASELINE_DIR ?? 'test-results-visual/baseline'}/{projectName}/{arg}{ext}`,
  workers: 1,
  timeout: 120_000,
  forbidOnly: Boolean(process.env.CI),
  expect: {
    timeout: 10_000,
    toHaveScreenshot: { animations: 'disabled', caret: 'hide', maxDiffPixels: 0, threshold: 0.05 },
  },
  reporter: [['list'], ['html', { open: 'never', outputFolder: 'test-results-visual/report' }]],
  use: { channel: 'chrome', trace: 'retain-on-failure' },
  projects: ['light', 'dark'].flatMap((theme) => [
    {
      name: `desktop-${theme}`,
      use: {
        ...devices['Desktop Chrome'],
        viewport: { width: 1440, height: 1000 },
        colorScheme: theme as 'light' | 'dark',
      },
    },
    { name: `mobile-${theme}`, use: { ...devices['Pixel 7'], colorScheme: theme as 'light' | 'dark' } },
  ]),
});
